// Return log result
const logResult = $input.item.json;

return {
  logged: true,
  logId: logResult?.id
};

// WF-60 Step 2: Normalize input to canonical shape; compute filter, transport & lookup flags.
const input = $input.first().json;

const transport = input.transport || 'wa';  // 'wa' (default) or 'slack' — set by canonical mappers
const direction = input.direction || 'inbound';
const isSlack = transport === 'slack';
const defaultMessageType = isSlack ? 'slack_text' : 'text';
const messageType = input.messageType || defaultMessageType;
const content = input.content ?? input.messageContent ?? input.userMessage ?? null;
const userId = input.userId ?? input.user?.id ?? null;
const consultationId = input.consultationId ?? input.user?.current_consultation_id ?? null;
const whatsappMessageId = input.whatsappMessageId ?? input.messageId ?? null;
const slackMessageTs = input.slackMessageTs ?? input.slack_message_ts ?? input.metadata?.slackMessageTs ?? null;
const phoneNumber = input.phoneNumber ?? input.phoneNumberFormatted ?? input.metadata?.phoneNumber ?? null;
const slackChannelId = input.slackChannelId ?? input.slack_channel_id ?? input.metadata?.slackChannelId ?? null;

// TD-034 whitespace guard (inbound text on either transport).
let filterReason = null;
if (direction === 'inbound' && (messageType === 'text' || messageType === 'slack_text')) {
  const trimmed = (content == null ? '' : String(content).trim());
  if (trimmed.length === 0) filterReason = 'whitespace_only_filtered';
}

// Lookup needed only if not filtered, no userId, and we have a lookup key (phone OR slack channel).
const hasLookupKey = !!(phoneNumber || slackChannelId);
const needsLookup = !filterReason && !userId && hasLookupKey;

// Choose lookup column based on transport / which key is present.
let lookupColumn = null;
let lookupValue = null;
if (needsLookup) {
  if (isSlack && slackChannelId) {
    lookupColumn = 'slack_channel_id';
    lookupValue = slackChannelId;
  } else if (phoneNumber) {
    lookupColumn = 'phone_number';
    lookupValue = phoneNumber;
  } else if (slackChannelId) {
    // Fallback: transport not explicitly 'slack' but only slack_channel_id present.
    lookupColumn = 'slack_channel_id';
    lookupValue = slackChannelId;
  }
}

return [{
  json: {
    transport,
    userId,
    consultationId,
    direction,
    messageType,
    content,
    whatsappMessageId,
    slackMessageTs,
    phoneNumber,
    slackChannelId,
    _filterReason: filterReason,
    _needsLookup: needsLookup,
    _lookupColumn: lookupColumn,
    _lookupValue: lookupValue,
    metadata: {
      transport,
      phoneNumber,
      slackChannelId,
      rawMessage: input.rawMessage || null,
      timestamp: input.timestamp || new Date().toISOString(),
      contactName: input.contactName || null,
      success: input.success ?? null,
      error: input.error || null,
      inboundMessageId: input.inboundMessageId || null,
      sentAt: input.sentAt || null
    }
  }
}];

// WF-60 Step 4b — no userId resolved.
// Inbound (pre-onboarding pendingUser): return pre_onboarding_user (FK NOT NULL means we cannot insert).
// Outbound: caller didn't pass userId — return no_userId.
const row = $input.first().json;
const direction = row.direction || 'inbound';
if (direction === 'inbound') {
  return [{ json: { logged: false, reason: 'pre_onboarding_user' } }];
}
return [{ json: { logged: false, reason: 'no userId — caller did not provide user identification' } }];

// Filter triggered upstream (e.g. TD-034 whitespace) — return structured skip.
const row = $input.first().json;
return [{ json: { logged: false, reason: row._filterReason || 'filtered' } }];

// Merge phone-lookup result back into the extracted row before the userId gate.
const extracted = $('Extract Message Data').first().json;
const lookup = $input.first()?.json;
const hitId = lookup?.id || null;
const hitConsultation = lookup?.current_consultation_id || null;

return [{
  json: {
    ...extracted,
    userId: extracted.userId || hitId,
    consultationId: extracted.consultationId || hitConsultation
  }
}];

// WF-60 Step 1: Discriminated-union entry guard (§2.6 data-contract-discipline-phase-1).
// Throws on structurally invalid payloads; passes through valid ones unchanged.
const input = $input.first().json;

// 1. transport — required, must be 'wa' or 'slack'
const transport = input.transport;
if (!transport || !['wa', 'slack'].includes(transport)) {
  throw new Error(`WF-60 input-contract violation: 'transport' must be 'wa' or 'slack' (got: ${JSON.stringify(transport)})`);
}

// 2. direction — required, must be 'inbound' or 'outbound'
const direction = input.direction;
if (!direction || !['inbound', 'outbound'].includes(direction)) {
  throw new Error(`WF-60 input-contract violation: 'direction' must be 'inbound' or 'outbound' (got: ${JSON.stringify(direction)})`);
}

// 3. messageType — required
const messageType = input.messageType;
if (!messageType) {
  throw new Error(`WF-60 input-contract violation: 'messageType' is required`);
}

// 4. Transport-variant required fields (only when userId absent — lookup keys)
const userId = input.userId ?? input.user?.id ?? null;
if (!userId) {
  if (transport === 'wa') {
    const phoneNumber = input.phoneNumber ?? input.phoneNumberFormatted ?? input.metadata?.phoneNumber ?? null;
    if (!phoneNumber) {
      throw new Error(`WF-60 input-contract violation: transport='wa' requires 'phoneNumber' when 'userId' is absent`);
    }
  } else if (transport === 'slack') {
    const slackChannelId = input.slackChannelId ?? input.slack_channel_id ?? input.metadata?.slackChannelId ?? null;
    if (!slackChannelId) {
      throw new Error(`WF-60 input-contract violation: transport='slack' requires 'slackChannelId' when 'userId' is absent`);
    }
    const slackMessageTs = input.slackMessageTs ?? input.slack_message_ts ?? input.metadata?.slackMessageTs ?? null;
    if (!slackMessageTs) {
      throw new Error(`WF-60 input-contract violation: transport='slack' requires 'slackMessageTs'`);
    }
  }
}

// Pass through unchanged.
return [$input.first()];

